test("void settled scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-B", "20");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "3"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-15", "to": "2026-03-28"})).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Cam,0.40,,paste")).toBe(1);
  const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
  expect(await ui.setSettingDated(pg_uma, "cap", "2.00", "2026-03-28", "2.00")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.pasteClaims(pg_wes, "Ben,25.00,,paste\nCam,4.00,2026-03-01,paste\nCam,7.77,2026-03-20,paste")).toBe(3);
  const c_ben_0 = await ui.claimAt(pg_wes, p_ben, 0);
  const c_cam_1 = await ui.claimAt(pg_wes, p_cam, 1);
  const c_cam_2 = await ui.claimAt(pg_wes, p_cam, 2);
  expect(await ui.watch(pg_wes, p_ben, true)).toBe(true);
  expect(await ui.bulkOpen(pg_wes, [c_cam_0, c_cam_1])).toEqual({ opened: 2, refused: 0 });
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("4.40");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("2.59");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.33");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.25");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("4.40");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("1.33");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("1.33");
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ben_0, "open")).toBe(true);
  expect(await ui.periodAction(pg_vic, "P1", "close")).toBe(true);
  expect(await ui.editClaim(pg_vic, c_cam_2, {"amount": "4.00"})).toBe(true);
  expect(await ui.setSettingDated(pg_vic, "cap", "", "2026-02-10", "2.00")).toBe(true);
  expect(await ui.statement(pg_vic, p_ben)).toBe(true);
  expect(await ui.hold(pg_vic, p_ben, {"from": "2026-02-25", "to": "2026-04-02"})).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.bulkSettle(pg_wes, [c_ben_0, c_cam_1, c_cam_0])).toEqual({ settled: 1, refused: 2 });
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("4.40");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("1.33");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.33");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("25.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("1.25");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.25");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("SETTLED");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("yes");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("29.40");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("3.25");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("1.33");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("3.25");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("1.33");
  expect(await ui.editPerson(pg_wes, p_ben, {"grade": "B", "gradeFrom": "2026-03-15"})).toBe(true);
  expect(await ui.claimAction(pg_wes, c_cam_2, "void")).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.claimAction(pg_vic, c_cam_0, "settle")).toBe(true);
  expect(await ui.split(pg_vic, p_cam, c_cam_1, "4.00")).toBeNull();
